-- Probes for 20261031100000_admissions_offer_links and
-- 20261031110000_admissions_offer_rpcs (admissions slice 11, checkpoint C1;
-- docs/admissions/PORT-PLAN.md, "Slice 11 plan"): the offer links, the
-- staff send RPCs and their daily cap, the confirm-step count, the email
-- status, the page's read and answer, the worker's send-time link, the
-- claim's offer rules, corrections (D-11j), the parent's audit row with no
-- actor (D-11i), and the outbox checks.
--
-- Generated by a script that inlines the fixture into every probe (the
-- harness gives each probe its own session). Invented ids 9e11b000-...
--
-- Run: npx supabase db reset && ./scripts/seed-local-dev-staff.sh
--      ./scripts/role-matrix.sh supabase/role-matrix/20261031100000_admissions_offer_links.sql
-- Run the probe files before the Edge Function integration tests (they
-- commit rows).
--
-- Value probes on the service RPCs run as postgres in setup (the service
-- guard lets postgres through, as it does service_role) and pass for every
-- role. Staff calls in setup run as the dev Manager through the JWT claim.
-- Comparisons use is distinct from, so a null result fails a check.
-- pg_temp.err(sql) returns 'SQLSTATE|DETAIL|message' for a statement that
-- fails, or 'ok'.

-- probe: S1 structure: grants, definer, pinned paths, helpers granted to nobody, links table closed, audit list 42 with the actor check, count 170, lock order
-- expect: anon,Attendant,Manager,Accountant,Auditor,Admissions Officer
create function pg_temp.err(p_sql text) returns text language plpgsql as $f$
declare v_state text; v_detail text; v_msg text;
begin
  execute p_sql;
  return 'ok';
exception when others then
  get stacked diagnostics v_state = returned_sqlstate, v_detail = pg_exception_detail, v_msg = message_text;
  return v_state || '|' || coalesce(v_detail, '') || '|' || v_msg;
end $f$;
do $$ declare f text; n integer; s text;
begin
  foreach f in array array['public.get_offer_by_link(text)', 'public.respond_to_offer(text, text)',
      'public.issue_offer_link(uuid, uuid)'] loop
    if has_function_privilege('anon', f, 'execute') or has_function_privilege('authenticated', f, 'execute')
       or not has_function_privilege('service_role', f, 'execute') then raise exception '% grants wrong', f; end if;
    if not (select prosecdef from pg_proc where oid = f::regprocedure) then raise exception '% not definer', f; end if;
    if not exists (select 1 from pg_proc where oid = f::regprocedure and proconfig::text like '%search_path=public%') then
      raise exception '% search_path', f; end if;
    if strpos((select prosrc from pg_proc where oid = f::regprocedure), '_require_public_service_caller') = 0 then
      raise exception '% has no service guard', f; end if;
  end loop;
  foreach f in array array['public.generate_offer(uuid)', 'public.reset_offer(uuid)', 'public.resend_offer_link(uuid)',
      'public.record_offer_response(uuid, text)', 'public.correct_offer_response(uuid, text, text)',
      'public.preview_offer_recipients(uuid)', 'public.get_offer_email_status(uuid)'] loop
    if has_function_privilege('anon', f, 'execute') or not has_function_privilege('authenticated', f, 'execute') then
      raise exception '% grants wrong', f; end if;
    if not (select prosecdef from pg_proc where oid = f::regprocedure) then raise exception '% not definer', f; end if;
    if not exists (select 1 from pg_proc where oid = f::regprocedure and proconfig::text like '%search_path=public%') then
      raise exception '% search_path', f; end if;
  end loop;
  foreach f in array array['public._offer_recipients(uuid)', 'public._offer_queue_send(uuid, text)',
      'public._offer_id_by_link(text)', 'public._admissions_offer_email_max_age()'] loop
    if has_function_privilege('anon', f, 'execute') or has_function_privilege('authenticated', f, 'execute')
       or has_function_privilege('service_role', f, 'execute') then raise exception '% executable by an API role', f; end if;
    if not exists (select 1 from pg_proc where oid = f::regprocedure and proconfig @> array['search_path=""']) then
      raise exception '% search_path', f; end if;
  end loop;
  if not (select relrowsecurity from pg_class where oid = 'public.application_offer_links'::regclass)
     or exists (select 1 from pg_policies where tablename = 'application_offer_links') then raise exception 'links RLS'; end if;
  foreach s in array array['anon', 'authenticated', 'service_role'] loop
    if has_table_privilege(s, 'public.application_offer_links', 'select,insert,update,delete,truncate,references,trigger') then
      raise exception 'links privilege for %', s; end if;
  end loop;
  if not has_column_privilege('authenticated', 'public.application_offers', 'link_generation', 'select')
     or not has_column_privilege('authenticated', 'public.application_offers', 'response_source', 'select')
     or has_column_privilege('authenticated', 'public.application_offers', 'token_hash', 'select') then
    raise exception 'offer column grants'; end if;
  select count(*) into n
  from regexp_matches((select pg_get_constraintdef(oid) from pg_constraint where conname = 'audit_log_action_check'), '''[a-z_]+''', 'g');
  if n is distinct from 42 then raise exception 'audit actions %', n; end if;
  if pg_get_constraintdef((select oid from pg_constraint where conname = 'audit_log_action_check')) not like '%application_offer_link_sent%'
     or pg_get_constraintdef((select oid from pg_constraint where conname = 'audit_log_action_check')) not like '%application_offer_responded%' then
    raise exception 'new actions missing'; end if;
  if pg_temp.err($q$insert into public.audit_log (branch_id, actor_id, action, entity_table, entity_id)
       values ((select id from public.branches limit 1), null, 'application_offer_changed', 'x', 'x')$q$) not like '23514|%' then
    raise exception 'null actor accepted for another action'; end if;
  select count(*) into n from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
  where ns.nspname = 'public' and has_function_privilege('anon', p.oid, 'execute');
  if n is distinct from 170 then raise exception 'anon-executable count is %, expected 170', n; end if;
  if exists (select proname from pg_proc where proname ~ 'offer' group by proname having count(*) > 1) then
    raise exception 'overloads'; end if;
  foreach f in array array['public.respond_to_offer(text, text)', 'public.issue_offer_link(uuid, uuid)'] loop
    s := (select prosrc from pg_proc where oid = f::regprocedure);
    if not (strpos(s, 'from public.applications a') < strpos(s, 'from public.application_decisions where application_id = v_app.id for update')
            and strpos(s, 'from public.application_decisions where application_id = v_app.id for update')
                < strpos(s, 'from public.application_offers where id = v_offer_id for update')
            and strpos(s, 'from public.applications a') > 0) then
      raise exception '% lock order', f; end if;
  end loop;
  s := (select prosrc from pg_proc where oid = 'public.respond_to_offer(text, text)'::regprocedure);
  if strpos(s, 'public._offer_id_by_link(p_token) is distinct from v_offer_id') <
     strpos(s, 'from public.application_offers where id = v_offer_id for update') then
    raise exception 'respond_to_offer does not re-read the link under the locks'; end if;
end $$;
-- as role:
select 1;

-- probe: S2 even with grants added by mistake, every JWT role is refused by the three service RPCs
-- expect: none
grant execute on function public.get_offer_by_link(text) to anon, authenticated;
grant execute on function public.respond_to_offer(text, text) to anon, authenticated;
grant execute on function public.issue_offer_link(uuid, uuid) to anon, authenticated;
-- as role:
do $$ declare n integer := 0; begin
  begin perform public.get_offer_by_link(repeat('a', 64)); n := n + 1; exception when others then null; end;
  begin perform public.respond_to_offer(repeat('a', 64), 'accepted'); n := n + 1; exception when others then null; end;
  begin perform public.issue_offer_link(gen_random_uuid(), gen_random_uuid()); n := n + 1; exception when others then null; end;
  if n = 0 then raise exception 'all refused'; end if;
end $$;

