-- probe: S4 rate limits: offer_ip 30 an hour, offer_global 300 an hour, offer_links_day 3 a day; offer_ip needs a hex key, offer_global takes none; offer_links_day is not a counted bucket
-- expect: anon,Attendant,Manager,Accountant,Auditor,Admissions Officer
create function pg_temp.err(p_sql text) returns text language plpgsql as $f$
declare v_state text; v_detail text; v_msg text;
begin
  execute p_sql;
  return 'ok';
exception when others then
  get stacked diagnostics v_state = returned_sqlstate, v_detail = pg_exception_detail, v_msg = message_text;
  return v_state || '|' || coalesce(v_detail, '') || '|' || v_msg;
end $f$;
do $$ begin
  if (select max_count || '|' || window_length from public._public_rate_limit_rule('offer_ip')) is distinct from '30|01:00:00'
     or (select max_count || '|' || window_length from public._public_rate_limit_rule('offer_global')) is distinct from '300|01:00:00'
     or (select max_count || '|' || window_length from public._public_rate_limit_rule('offer_links_day')) is distinct from '3|1 day' then
    raise exception 'rule values'; end if;
  if public.check_public_rate_limit('offer_ip', repeat('a', 64)) is distinct from true
     or public.check_public_rate_limit('offer_global') is distinct from true then raise exception 'buckets refused'; end if;
  if pg_temp.err($q$select public.check_public_rate_limit('offer_ip')$q$) = 'ok'
     or pg_temp.err($q$select public.check_public_rate_limit('offer_ip', 'not hex')$q$) = 'ok'
     or pg_temp.err($q$select public.check_public_rate_limit('offer_global', repeat('a', 64))$q$) = 'ok'
     or pg_temp.err($q$select public.check_public_rate_limit('offer_links_day', repeat('a', 64))$q$) = 'ok' then
    raise exception 'a wrong bucket call was accepted'; end if;
end $$;
-- as role:
select 1;

