do $$ declare o public.application_offers; begin
  select * into o from public.application_offers where application_id = '9e11b000-0000-4000-8000-000400000001';
  if o.token_hash is not null or o.link_generation is distinct from 1 or o.response is distinct from 'pending' or o.response_source is not null then
    raise exception 'offer %', o; end if;
  if (select array_agg(recipient_email || '|' || status || '|' || event_key || '|' || cardinality(application_ids) order by recipient_email)
      from public.admissions_email_outbox where offer_id = o.id)
     is distinct from array['g1@example.test|pending|offer:' || o.id || ':1|1', 'g2@example.test|pending|offer:' || o.id || ':1|1'] then
    raise exception 'outbox rows wrong'; end if;
  if exists (select 1 from public.admissions_email_outbox where offer_id = o.id
             and (kind is distinct from 'offer' or params - 'references' is distinct from '{}'::jsonb
                  or params -> 'references' -> 0 ->> 'grade' is distinct from 'Grade 3'
                  or params -> 'references' -> 0 ->> 'reference' !~ '^APP-')) then
    raise exception 'params wrong'; end if;
  if (select count(*) from public.audit_log where entity_id = o.id::text and action = 'application_offer_changed') is distinct from 1
     or (select after ->> 'send' || '|' || (after ->> 'recipients') || '|' || (after ->> 'generation')
         from public.audit_log where entity_id = o.id::text and action = 'application_offer_link_sent') is distinct from 'generate|2|1'
     or exists (select 1 from public.audit_log where entity_id = o.id::text and (after::text like '%@%' or after::text ~ '[0-9a-f]{64}')) then
    raise exception 'audit wrong'; end if;
end $$;

