from public.claim_admissions_emails(50, 1000) c where c.kind = 'offer';
select public.respond_to_offer((select result ->> 'token' from t_links limit 1), 'declined');
insert into public.admissions_email_outbox (event_key, kind, recipient_email, application_ids, params, offer_id)
select 'offer:' || o.id || ':1', 'offer', 'late@example.test', array['9e11b000-0000-4000-8000-000400000001'::uuid], (select params from public.admissions_email_outbox where kind = 'offer' limit 1), o.id from public.application_offers o where o.application_id = '9e11b000-0000-4000-8000-000400000001';
