do $$ declare r jsonb; begin
  r := public.reset_offer('9e11b000-0000-4000-8000-000400000001');
  if r ? 'token' or (r ->> 'emails_queued')::int is distinct from 2 or r ->> 'stage' is distinct from 'offer' then raise exception 'result %', r; end if;
end $$;
