do $$ declare o public.application_offers; begin
  select * into o from public.application_offers where application_id = '9e11b000-0000-4000-8000-000400000001';
  if o.link_generation is distinct from 2 or o.response is distinct from 'pending' or o.response_source is not null or o.responded_at is not null then
    raise exception 'offer %', o; end if;
  if exists (select 1 from public.application_offer_links where revoked_at is null) then raise exception 'live link left'; end if;
  if (select status from public.admissions_email_outbox where recipient_email = 'late@example.test') is distinct from 'expired' then
    raise exception 'old waiting email not expired'; end if;
  if (select count(*) from public.admissions_email_outbox where event_key like '%:2' and status = 'pending') is distinct from 2 then
    raise exception 'new emails'; end if;
  if public.get_offer_by_link((select result ->> 'token' from t_links limit 1)) is not null then raise exception 'old link opens'; end if;
  delete from public.guardians where family_id = '9e11b000-0000-4000-8000-000100000001';
  update public.application_offers set response = 'declined', responded_at = now() where id = o.id;
  perform set_config('request.jwt.claims', (select json_build_object('sub', id, 'role', 'authenticated')::text
    from public.staff where role = 'Manager' and active order by id limit 1), true);
  if (public.reset_offer('9e11b000-0000-4000-8000-000400000001') ->> 'emails_queued')::int is distinct from 0 then raise exception 'sent with no address'; end if;
  perform set_config('request.jwt.claims', '{}', true);
  if (select link_generation from public.application_offers where id = o.id) is distinct from 3 then raise exception 'generation not moved'; end if;
  if (select count(*) from public.audit_log where entity_id = o.id::text and action = 'application_offer_link_sent') is distinct from 2 then
    raise exception 'link_sent written with no address'; end if;
end $$;

