create temp table t_links (outbox_id uuid, recipient text, result jsonb) on commit drop;
insert into t_links
select c.id, c.recipient_email, public.issue_offer_link(c.id, c.claim_token)
from public.claim_admissions_emails(50, 1000) c where c.kind = 'offer';
do $$ declare t text; r jsonb; o public.application_offers; b text; begin
  if (select count(*) from t_links where result ->> 'status' = 'issued') is distinct from 2 then raise exception 'not issued'; end if;
  t := (select result ->> 'token' from t_links where recipient = 'g1@example.test');
  if t !~ '^[0-9a-f]{64}$' then raise exception 'token'; end if;
  if (select count(*) from public.application_offer_links where token_hash = encode(extensions.digest(t, 'sha256'), 'hex')) is distinct from 1 then
    raise exception 'hash'; end if;
  if exists (select 1 from public.admissions_email_outbox x where row_to_json(x)::text like '%' || t || '%')
     or exists (select 1 from public.application_offer_links x where row_to_json(x)::text like '%' || t || '%')
     or exists (select 1 from public.audit_log x where row_to_json(x)::text like '%' || t || '%') then
    raise exception 'raw token stored'; end if;
  select coalesce(public_label, name) into b from public.branches order by created_at limit 1;
  r := public.get_offer_by_link(t);
  if r ->> 'state' is distinct from 'open' or r ->> 'first_name' is distinct from 'Ama' or r ->> 'grade' is distinct from 'Grade 3'
     or r ->> 'academic_year' is distinct from '2027/2028' or r ->> 'campus' is distinct from b or r ->> 'respond_by' is null
     or (r - array['state', 'first_name', 'grade', 'academic_year', 'campus', 'respond_by']) is distinct from '{}'::jsonb then
    raise exception 'read %', r; end if;
  if public.respond_to_offer(t, 'accepted') is distinct from '{"status": "recorded", "response": "accepted"}'::jsonb then raise exception 'respond'; end if;
  select * into o from public.application_offers where application_id = '9e11b000-0000-4000-8000-000400000001';
  if o.response is distinct from 'accepted' or o.response_source is distinct from 'offer_link' or o.responded_at is null then raise exception 'offer %', o; end if;
  if (select stage from public.applications where id = '9e11b000-0000-4000-8000-000400000001') is distinct from 'offer' then raise exception 'stage moved'; end if;
  if (select count(*) from public.audit_log where action = 'application_offer_responded' and actor_id is null
      and after ->> 'response' = 'accepted' and after ->> 'source' = 'offer_link' and entity_id = o.id::text) is distinct from 1 then
    raise exception 'audit'; end if;
  if (select params ->> 'response' || '|' || (params ->> 'application_id') from public.admissions_email_outbox where kind = 'offer_staff')
     is distinct from 'accepted|9e11b000-0000-4000-8000-000400000001' then raise exception 'staff alert'; end if;
  if public.respond_to_offer(t, 'declined') is distinct from '{"status": "answered", "response": "accepted"}'::jsonb
     or public.respond_to_offer((select result ->> 'token' from t_links where recipient = 'g2@example.test'), 'declined')
        is distinct from '{"status": "answered", "response": "accepted"}'::jsonb
     or public.get_offer_by_link(t) is distinct from '{"state": "answered", "response": "accepted"}'::jsonb then
    raise exception 'answered'; end if;
  if (select count(*) from public.audit_log where action = 'application_offer_responded') is distinct from 1
     or (select count(*) from public.admissions_email_outbox where kind = 'offer_staff') is distinct from 1 then raise exception 'second write'; end if;
end $$;
