select c.id, c.recipient_email, public.issue_offer_link(c.id, c.claim_token)
from public.claim_admissions_emails(50, 1000) c where c.kind = 'offer';
do $$ declare t text := (select result ->> 'token' from t_links limit 1); begin
  if public.get_offer_by_link(repeat('b', 64)) is not null or public.respond_to_offer(repeat('b', 64), 'accepted') is not null
     or public.get_offer_by_link('ABC') is not null or public.get_offer_by_link(null) is not null
     or public.get_offer_by_link(upper(t)) is not null then raise exception 'unknown or malformed opened'; end if;
  update public.application_offers set expires_at = now() - interval '1 second' where application_id = '9e11b000-0000-4000-8000-000400000001';
  if public.get_offer_by_link(t) is not null or public.respond_to_offer(t, 'accepted') is not null then raise exception 'expired'; end if;
  update public.application_offers set expires_at = now() + interval '5 days', response = 'withdrawn' where application_id = '9e11b000-0000-4000-8000-000400000001';
  if public.get_offer_by_link(t) is not null or public.respond_to_offer(t, 'accepted') is not null then raise exception 'withdrawn'; end if;
  update public.application_offers set response = 'pending', link_generation = link_generation + 1 where application_id = '9e11b000-0000-4000-8000-000400000001';
  if public.get_offer_by_link(t) is not null or public.respond_to_offer(t, 'accepted') is not null then raise exception 'older generation'; end if;
  if exists (select 1 from public.audit_log where action = 'application_offer_responded')
     or exists (select 1 from public.admissions_email_outbox where kind = 'offer_staff') then raise exception 'written'; end if;
end $$;
-- as role:
select 1;

