do $$ declare c record; r jsonb; begin
  select * into c from public.claim_admissions_emails(50, 1000) x where x.kind = 'offer' limit 1;
  if public.issue_offer_link(c.id, gen_random_uuid()) is not null then raise exception 'wrong claim'; end if;
  if public.issue_offer_link(gen_random_uuid(), c.claim_token) is not null then raise exception 'wrong row'; end if;
  r := public.issue_offer_link(c.id, c.claim_token);
  if r ->> 'status' is distinct from 'issued' then raise exception 'not issued %', r; end if;
  if pg_temp.err(format('select public.issue_offer_link(%L, %L)', c.id, c.claim_token)) = 'ok' then raise exception 'second issue'; end if;
end $$;
-- each case on a fresh claim of the other row
create temp table t_case (n int) on commit drop;
do $$ declare c record; v text; r jsonb; begin
  foreach v in array array['generation', 'answered', 'expired', 'age', 'age_after_claim'] loop
    update public.admissions_email_outbox set status = 'pending', claim_token = null, claimed_at = null, created_at = now(), requeued_at = null
    where kind = 'offer' and recipient_email = 'g2@example.test';
    update public.application_offers set link_generation = 1, response = 'pending', response_source = null, expires_at = now() + interval '5 days' where application_id = '9e11b000-0000-4000-8000-000400000001';
    if v = 'generation' then update public.application_offers set link_generation = 2 where application_id = '9e11b000-0000-4000-8000-000400000001'; end if;
    if v = 'answered' then update public.application_offers set response = 'accepted', response_source = 'staff' where application_id = '9e11b000-0000-4000-8000-000400000001'; end if;
    if v = 'age' then update public.admissions_email_outbox set created_at = now() - interval '7 days 1 minute' where recipient_email = 'g2@example.test'; end if;
    select * into c from public.claim_admissions_emails(50, 1000) x where x.kind = 'offer';
    if c.id is null then
      if v = 'age' then
        if (select status from public.admissions_email_outbox where recipient_email = 'g2@example.test') is distinct from 'expired' then raise exception 'age not expired by the claim'; end if;
        continue;
      end if;
      raise exception 'no claim for %', v;
    end if;
    if v = 'expired' then update public.application_offers set expires_at = now() - interval '1 second' where application_id = '9e11b000-0000-4000-8000-000400000001'; end if;
    if v = 'age_after_claim' then update public.admissions_email_outbox set created_at = now() - interval '7 days 1 minute' where id = c.id; end if;
    r := public.issue_offer_link(c.id, c.claim_token);
    if r is distinct from '{"status": "expired"}'::jsonb then raise exception 'case % returned %', v, r; end if;
    if (select status from public.admissions_email_outbox where id = c.id) is distinct from 'expired' then raise exception 'case % row not expired', v; end if;
  end loop;
end $$;
-- as role:
select 1;

